mapper.select:
SELECT
    ROUND(SUM(10000*PROFIT_AMT/CAPITAL),12) AS PYieldSumSince
FROM  
(
    SELECT
        P_YIELD,
        CAPITAL,
        PROFIT_AMT,
        a.rn
    FROM (
SELECT tmp.*,
@rownum := @rownum + 1 rownum, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID
and @HAPPEN_DATE = tmp.HAPPEN_DATE
), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @HAPPEN_DATE := tmp.HAPPEN_DATE /* 分组条件1 */
FROM (
/* 数据源 */
SELECT * FROM BOK_STAT_BOK_POSITION ORDER BY BOOKSET_DATE DESC
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@HAPPEN_DATE := null,
@rank := 0) a
) A
    WHERE
        A.HAPPEN_DATE <= #{bookDate}

            AND A.HAPPEN_DATE > #{queryDate}

        AND A.BOOKSET_ID = #{booksetId}
        AND A.BOOK_DATE <= #{bookDate}
        AND A.CAPITAL != 0 AND A.CAPITAL IS NOT NULL
)
WHERE rn = 1

	   SELECT 
		  SUM(END_DAYS_1*TDY_COST_AMT) AS remainTermSum,
          SUM(END_DAYS_2*TDY_COST_AMT) AS remainDurationSum,
          SUM(TDY_COST_AMT) AS costSum
	   FROM 
	   (
	       SELECT 
               ifnull(A.END_DAYS_1,0) AS END_DAYS_1,
               ifnull(A.END_DAYS_2,0) AS END_DAYS_2,
               CASE WHEN 
                   A.FINPROD_TYPE = #{finprodType}
               THEN
                   ifnull(A.END_DAYS_COST_AMT,0)
               ELSE
                   ifnull(A.TDY_COST_AMT,0)
               END AS TDY_COST_AMT,
    	       a.rn
	       FROM (
        SELECT tmp.*,
        @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
        IF(
        (
        @BOOKSET_ID = tmp.BOOKSET_ID
        and @HAPPEN_DATE = tmp.HAPPEN_DATE
        and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID
        ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
        @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
        , @HAPPEN_DATE := tmp.HAPPEN_DATE /* 分组条件1 */
        , @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件1 */
        FROM (
        /* 数据源 */
        SELECT * FROM BOK_STAT_DET_POSIITON ORDER BY BOOK_SUMMARY_ORDER desc
        ) tmp,
        /* 定义临时变量池 */
        (SELECT @rownum := 0,
        @BOOKSET_ID := null,
        @BOK_DETAIL_ID := null,
        @HAPPEN_DATE := null,
        @rank := 0) a
        ) A
	       WHERE A.HAPPEN_DATE = #{bookDate}
               AND A.BOOKSET_ID = #{booksetId}
               AND A.BOOK_DATE <= #{bookDate}
               AND A.FINPROD_TYPE IN 

                   #{item}

	   ) WHERE rn = 1

SELECT
SUM(balance) AS recvBalance
FROM (
SELECT
A.O_AMT_HAPPEN_DATE as balance,
a.RW
FROM  (
SELECT tmp.*,
@rownum := @rownum + 1 rownum, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID
and @BASE_SUBJECT_NATURE = tmp.BASE_SUBJECT_NATURE
and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID
and @BRANCH = tmp.BRANCH
and @O_CCY = tmp.O_CCY
), @rank := @rank + 1, @rank := 1) AS rw, /* 分组虚拟列行标 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @BASE_SUBJECT_NATURE := tmp.BASE_SUBJECT_NATURE /* 分组条件1 */
, @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件1 */
, @BRANCH := tmp.BRANCH /* 分组条件1 */
, @O_CCY := tmp.O_CCY /* 分组条件1 */
FROM (
/* 数据源 */
SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER desc
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@BOK_DETAIL_ID := null,
@BASE_SUBJECT_NATURE := null,
@BRANCH := null,
@O_CCY := null,
@rank := 0) a
) A
INNER JOIN BOK_DETAIL_ID B
ON A.BOOKSET_ID = B.BOOKSET_ID
AND A.BUSI_ID = B.BUSI_ID
AND B.BUSI_DETAIL_TYPE = #{finprodType}
WHERE A.BOOKSET_ID = #{booksetId}
AND A.BOOK_DATE <= #{bookDate}
AND A.HAPPEN_DATE <= #{bookDate}
AND A.BASE_SUBJECT_NATURE IN

    #{baseSubNature}





















)
WHERE RW = 1

SELECT
    ROUND(SUM(10000*PROFIT_AMT/CAPITAL),12) AS PYieldSumSince
FROM  
(
    SELECT
        P_YIELD,
        CAPITAL,
        PROFIT_AMT,
        a.rn
    FROM (
SELECT tmp.*,
@rownum := @rownum + 1 rownum, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID
and @HAPPEN_DATE = tmp.HAPPEN_DATE
), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @HAPPEN_DATE := tmp.HAPPEN_DATE /* 分组条件1 */
FROM (
/* 数据源 */
SELECT * FROM BOK_STAT_BOK_POSITION ORDER BY BOOKSET_DATE DESC
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@HAPPEN_DATE := null,
@rank := 0) a
) A
    WHERE
        A.HAPPEN_DATE <= #{bookDate}

            AND A.HAPPEN_DATE > #{queryDate}

        AND A.BOOKSET_ID = #{booksetId}
        AND A.BOOK_DATE <= #{bookDate}
        AND A.CAPITAL != 0 AND A.CAPITAL IS NOT NULL

            AND A.LAYERING_ID = #{layeringId}

)
WHERE rn = 1

SELECT A.BOOKSET_ID booksetId, A.BUSI_ID busiId, A.BUSI_DETAIL_TYPE busiDetailType, A.VDATE vDate, A.BRANCH branch, A.CASH_ID cashId, A.BASIS basis FROM ( SELECT FINPROD.BOOKSET_ID, FINPROD.BUSI_ID, FINPROD.BUSI_DETAIL_TYPE, FINPROD.VDATE, FINPROD.BRANCH, FINPROD.CASH_ID, D.BASIS, D.rn AS newResult FROM ( SELECT tmp.*, @rownum := @rownum + 1 rownum, /* 虚拟列行标 */ IF( ( @CASH_ID = tmp.CASH_ID ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */ @CASH_ID := tmp.CASH_ID /* 分组条件1 */ FROM ( /* 数据源 */ SELECT * FROM FIN_CASH_CALC_RULE ORDER BY EFF_DATE DESC ) tmp, /* 定义临时变量池 */ (SELECT @rownum := 0, @CASH_ID := null, @rank := 0) a ) D,( SELECT A.BOOKSET_ID, A.BUSI_ID, A.BUSI_DETAIL_TYPE, A.VDATE, A.BRANCH, B.CASH_ID FROM BOK_ACCT_LAYERING_INFO A, FIN_CASH_INFO B ,BOK_BOOKSET C WHERE A.BUSI_ID = B.FINPROD_ID
AND A.BRANCH = B.BRANCH AND A.BOOKSET_ID = C.BOOKSET_ID AND B.CASH_TYPE_2 = 'C04' AND A.BOOKSET_ID = #{booksetId} AND C.ACCT_SUBJECT_ID = #{acctSubjectId}
AND A.LAYERING_ID = #{layeringId}
) FINPROD WHERE D.CASH_ID = FINPROD.CASH_ID AND D.EFF_DATE <= #{bookDate} ) A WHERE newResult = 1
